package escuela.personal.controller;
import escuela.personal.dto.*;
import escuela.personal.service.*;
import escuela.admin.dto.*;
import escuela.admin.support.MensajeErrorFormulario;
import escuela.common.exception.ReglaNegocioException;
import escuela.seguridad.service.AlcanceDatosService;
import escuela.institucion.service.InstitucionService;
import escuela.institucion.repository.PlantelRepository;
import escuela.institucion.entity.Plantel;
import jakarta.validation.Valid;
import lombok.RequiredArgsConstructor;
import org.springframework.data.domain.*;
import org.springframework.data.jpa.domain.Specification;
import org.springframework.security.core.Authentication;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.validation.BindingResult;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.servlet.mvc.support.RedirectAttributes;
import org.springframework.http.*;
import org.springframework.core.io.Resource;
import org.springframework.web.multipart.MultipartFile;
import jakarta.servlet.http.HttpServletResponse;
import java.time.LocalDate;
import java.util.*;
import java.io.IOException;

@Controller @RequiredArgsConstructor @RequestMapping("/admin/empleados")
public class EmpleadoAdminController {
 private final EmpleadoService service;private final ExcelEmpleadoService excel;private final InstitucionService instituciones;private final AlcanceDatosService alcance;
 private final FotografiaEmpleadoService fotos;private final PlantelRepository planteles;
 private final CambioPrincipalEmpleadoService cambioPrincipal;
 private final OrganizacionLaboralService organizacion;
 @GetMapping String listar(@RequestParam(required=false)Long institucionId,@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="TODOS")String estado,@RequestParam(defaultValue="0")int pagina,@RequestParam(defaultValue="25")int tamanio,@RequestParam(required=false)Long empleadoId,@RequestParam(defaultValue="")String empleadoTexto,Authentication a,Model m){var f=new FiltroEmpleado(institucionId,q,estado,pagina,tamanio,empleadoId,empleadoTexto).normalizado();try{m.addAttribute("resultado",service.listar(f));}catch(ReglaNegocioException e){m.addAttribute("errorOperacion",e.getMessage());m.addAttribute("resultado",Page.empty());}m.addAttribute("filtro",f);m.addAttribute("empleadoFiltro",f.empleadoId()==null?f.empleadoTexto():etiquetaEmpleado(f.empleadoId()));m.addAttribute("retornoEmpleado",escuela.admin.support.RetornoListadoCobranza.empleados(f));menu(a,m);return "admin/empleados";}
 @GetMapping("/excel")void excel(@RequestParam(required=false)Long institucionId,@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="TODOS")String estado,@RequestParam(required=false)Long empleadoId,@RequestParam(defaultValue="")String empleadoTexto,HttpServletResponse r)throws IOException{
  // Validar antes de abrir la respuesta binaria.
  var f=new FiltroEmpleado(institucionId,q,estado,0,100,empleadoId,empleadoTexto);service.listar(new FiltroEmpleado(institucionId,q,estado,0,10,empleadoId,empleadoTexto));r.setContentType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");r.setHeader("Content-Disposition","attachment; filename=empleados.xlsx");excel.exportar(f,r.getOutputStream());}
 @GetMapping("/nuevo")String nuevo(Authentication a,Model m){if(!service.permitido("EMPLEADO_ADMINISTRAR"))throw new org.springframework.security.access.AccessDeniedException("Sin permiso para registrar empleados");var f=new EmpleadoForm();var list=alcance.filtrarInstituciones(instituciones.listar());if(list.size()==1)f.setInstitucionId(list.getFirst().id());m.addAttribute("form",f);preparar(null,a,m,0,0);return "admin/empleado-form";}
 @GetMapping("/{id}")String detalle(@PathVariable Long id,@RequestParam(defaultValue="0")int paginaPlanteles,@RequestParam(defaultValue="0")int paginaHistorial,@RequestParam(required=false)Integer paginaProximas,@RequestParam(required=false)Integer paginaAnteriores,Authentication a,Model m){var e=service.obtener(id);m.addAttribute("form",e.formulario());preparar(id,a,m,paginaPlanteles,paginaHistorial);if(laboralLectura()){if(paginaProximas!=null)m.addAttribute("proximas",service.plantelesGrupo(id,paginaProximas,"PROXIMAS"));if(paginaAnteriores!=null)m.addAttribute("anteriores",service.plantelesGrupo(id,paginaAnteriores,"HISTORICAS"));m.addAttribute("abrirProximas",paginaProximas!=null);m.addAttribute("abrirAnteriores",paginaAnteriores!=null);}return "admin/empleado-form";}
 @GetMapping("/{id}/planteles/cambio-principal/vista-previa") @ResponseBody ResponseEntity<?> vistaPrincipal(@PathVariable Long id,@RequestParam LocalDate fecha,@RequestParam Long plantelId,@RequestParam(defaultValue="true")boolean conservarAnterior){try{return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(cambioPrincipal.visualizar(id,fecha,plantelId,conservarAnterior));}catch(ReglaNegocioException e){return ResponseEntity.badRequest().cacheControl(CacheControl.noStore()).body(Map.of("mensaje",e.getMessage()));}}
 @PostMapping("/{id}/planteles/cambio-principal")String cambiarPrincipal(@PathVariable Long id,@Valid @ModelAttribute CambioPrincipalForm form,BindingResult errores,RedirectAttributes f){service.autorizar(id,true,true);try{if(errores.hasErrors())throw new ReglaNegocioException("Revisa fecha, plantel y motivo; vuelve a visualizar el cambio antes de confirmar.");cambioPrincipal.confirmar(id,form);f.addFlashAttribute("mensaje","Cambio de plantel principal guardado; se conservaron las asignaciones anteriores y no se modificaron permisos ni grupos.");}catch(ReglaNegocioException|org.springframework.dao.DataIntegrityViolationException|org.springframework.orm.ObjectOptimisticLockingFailureException ex){f.addFlashAttribute("errorOperacion",MensajeErrorFormulario.desde(ex));}f.addFlashAttribute("pestanaActiva","planteles");return "redirect:/admin/empleados/"+id+"#planteles-empleado";}
 @PostMapping String crear(@Valid @ModelAttribute("form")EmpleadoForm f,BindingResult errors,Authentication a,Model m,RedirectAttributes flash){if(errors.hasErrors()){preparar(null,a,m,0,0);return "admin/empleado-form";}try{Long id=service.guardar(null,f);flash.addFlashAttribute("mensaje","Empleado registrado sin crear acceso ni nómina");return "redirect:/admin/empleados/"+id;}catch(ReglaNegocioException|org.springframework.dao.DataIntegrityViolationException ex){m.addAttribute("errorOperacion",MensajeErrorFormulario.desde(ex));preparar(null,a,m,0,0);return "admin/empleado-form";}}
 @PostMapping("/{id}")String guardar(@PathVariable Long id,@Valid @ModelAttribute("form")EmpleadoForm f,BindingResult errors,Authentication a,Model m,RedirectAttributes flash){service.autorizar(id,false,true);if(errors.hasErrors()){preparar(id,a,m,0,0);m.addAttribute("pestanaActiva","personales");return "admin/empleado-form";}try{service.guardar(id,f);flash.addFlashAttribute("mensaje","Datos personales actualizados; no se modificaron cuentas ni actividad docente");return "redirect:/admin/empleados/"+id+"#personales-empleado";}catch(ReglaNegocioException|org.springframework.dao.DataIntegrityViolationException|org.springframework.orm.ObjectOptimisticLockingFailureException ex){m.addAttribute("errorOperacion",MensajeErrorFormulario.desde(ex));m.addAttribute("pestanaActiva","personales");preparar(id,a,m,0,0);return "admin/empleado-form";}}
 @PostMapping("/{id}/perfil")String perfil(@PathVariable Long id,@RequestParam Long version,@RequestParam boolean activo,@RequestParam(defaultValue="")String codigoDocente,RedirectAttributes f){try{service.perfil(id,version,activo,codigoDocente);f.addFlashAttribute("mensaje","Perfil docente actualizado; la cuenta de acceso no cambió");}catch(ReglaNegocioException|org.springframework.dao.DataIntegrityViolationException|org.springframework.orm.ObjectOptimisticLockingFailureException ex){f.addFlashAttribute("errorOperacion",MensajeErrorFormulario.desde(ex));}f.addFlashAttribute("pestanaActiva","docente");return "redirect:/admin/empleados/"+id+"#docente-empleado";}
 @PostMapping("/{id}/laboral")String laboral(@PathVariable Long id,@Valid @ModelAttribute("laboralForm")LaboralForm form,BindingResult errors,Authentication a,Model m,RedirectAttributes f){service.autorizar(id,true,true);if(!errors.hasErrors())try{service.guardarLaboral(id,form);f.addFlashAttribute("mensaje","Información laboral guardada; cuentas y asignaciones sin cambios");return "redirect:/admin/empleados/"+id+"#laboral-empleado";}catch(ReglaNegocioException|org.springframework.dao.DataIntegrityViolationException|org.springframework.orm.ObjectOptimisticLockingFailureException ex){m.addAttribute("errorOperacion",MensajeErrorFormulario.desde(ex));}m.addAttribute("form",service.obtener(id).formulario());m.addAttribute("pestanaActiva","laboral");preparar(id,a,m,0,0);return "admin/empleado-form";}
 @PostMapping("/{id}/planteles")String plantel(@PathVariable Long id,@Valid @ModelAttribute("plantelForm")PlantelEmpleadoForm form,BindingResult errors,Authentication a,Model m,RedirectAttributes f){service.autorizar(id,true,true);if(!errors.hasErrors())try{service.agregarPlantel(id,form);f.addFlashAttribute("mensaje","Asignación laboral registrada sin conceder permisos");return "redirect:/admin/empleados/"+id+"#planteles-empleado";}catch(ReglaNegocioException|org.springframework.dao.DataIntegrityViolationException ex){m.addAttribute("errorOperacion","Revisa el plantel y las vigencias: no se permite repetir un plantel durante las mismas fechas ni tener dos principales simultáneos.");}m.addAttribute("form",service.obtener(id).formulario());m.addAttribute("pestanaActiva","planteles");preparar(id,a,m,0,0);return "admin/empleado-form";}
 @PostMapping("/{id}/planteles/{relacion}/finalizar")String finalizar(@PathVariable Long id,@PathVariable Long relacion,@RequestParam Long version,@RequestParam LocalDate fecha,RedirectAttributes f){try{service.finalizarPlantel(id,relacion,version,fecha);f.addFlashAttribute("mensaje","Vigencia laboral finalizada; grupos, cuenta y otros planteles no cambiaron");}catch(ReglaNegocioException|org.springframework.dao.DataIntegrityViolationException|org.springframework.orm.ObjectOptimisticLockingFailureException ex){f.addFlashAttribute("errorOperacion",MensajeErrorFormulario.desde(ex));}f.addFlashAttribute("pestanaActiva","planteles");return "redirect:/admin/empleados/"+id+"#planteles-empleado";}
 @PostMapping("/{id}/fotografia")String fotografia(@PathVariable Long id,@RequestParam MultipartFile archivo,RedirectAttributes f){service.autorizar(id,false,true);try{fotos.asignar(id,archivo);f.addFlashAttribute("mensaje","Foto del expediente actualizada; fotografía de usuario independiente");}catch(ReglaNegocioException ex){f.addFlashAttribute("errorOperacion",ex.getMessage());}return "redirect:/admin/empleados/"+id;}
 @GetMapping("/{id}/fotografia")ResponseEntity<Resource> foto(@PathVariable Long id){service.autorizar(id,false,false);var d=fotos.descargar(id);return ResponseEntity.ok().cacheControl(CacheControl.noStore()).contentType(MediaType.parseMediaType(d.tipoMime())).contentLength(d.tamanoBytes()).header(HttpHeaders.CONTENT_DISPOSITION,ContentDisposition.inline().filename(d.nombreOriginal(),java.nio.charset.StandardCharsets.UTF_8).build().toString()).body(d.recurso());}
 @GetMapping("/{id}/planteles/buscar") @ResponseBody ResultadoAutocompletado buscar(@PathVariable Long id,@RequestParam(defaultValue="")String q){var e=service.autorizar(id,true,true);String t=q.strip().toLowerCase(Locale.ROOT);if(!t.isEmpty()&&t.length()<3)return ResultadoAutocompletado.vacio();String patron="%"+t.substring(0,Math.min(100,t.length())).replace("\\","\\\\").replace("%","\\%").replace("_","\\_")+"%";Specification<Plantel> s=(r,x,b)->b.and(b.equal(r.get("institucion").get("id"),e.getInstitucion().getId()),b.isTrue(r.get("activo")),b.or(b.like(b.lower(r.get("codigo")),patron,'\\'),b.like(b.lower(r.get("nombre")),patron,'\\')));var result=planteles.findAll(s,PageRequest.of(0,11,Sort.by("nombre","id")));return new ResultadoAutocompletado(result.stream().limit(10).map(p->new OpcionAutocompletado(p.getId(),p.getCodigo()+" · "+p.getNombre(),"Plantel laboral")).toList(),result.getNumberOfElements()>10);}
 private void preparar(Long id,Authentication a,Model m,int pp,int ph){menu(a,m);m.addAttribute("edicion",id!=null);m.addAttribute("id",id);m.addAttribute("instituciones",alcance.filtrarInstituciones(instituciones.listar()));if(id!=null){m.addAttribute("empleado",service.obtener(id));if(laboralLectura()){if(!m.containsAttribute("laboralForm"))m.addAttribute("laboralForm",service.laboral(id));m.addAttribute("actuales",service.plantelesGrupo(id,pp,"ACTUALES"));m.addAttribute("proximas",service.plantelesGrupo(id,0,"PROXIMAS"));m.addAttribute("anteriores",service.plantelesGrupo(id,0,"HISTORICAS"));m.addAttribute("resumenPrincipal",service.resumenPrincipal(id));m.addAttribute("hoyLaboral",service.hoyLaboral(id));m.addAttribute("fechaCambioSugerida",service.hoyLaboral(id).plusDays(1));m.addAttribute("historial",service.historial(id,ph));if(service.permitido("CONDICION_SALARIAL_LEER")||service.permitido("CONDICION_SALARIAL_ADMINISTRAR"))m.addAttribute("asignacionActual",organizacion.asignaciones(id,"","ACTUAL",null,null,0,10).stream().findFirst().orElse(null));if(!m.containsAttribute("plantelForm"))m.addAttribute("plantelForm",new PlantelEmpleadoForm());}}}
 @GetMapping("/{id}/puestos/buscar") @ResponseBody ResponseEntity<ResultadoAutocompletado> buscarPuestos(@PathVariable Long id,@RequestParam(defaultValue="")String q){var filas=service.buscarPuestosLaborales(id,q);return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(new ResultadoAutocompletado(filas.stream().limit(10).toList(),filas.size()>10));}
 private boolean laboralLectura(){return service.permitido("EMPLEADO_LABORAL_LEER")||service.permitido("EMPLEADO_LABORAL_ADMINISTRAR");}
 private String etiquetaEmpleado(Long id){var e=service.obtener(id);return e.codigo()+" · "+e.nombre();}
 @GetMapping("/buscar")@ResponseBody ResponseEntity<ResultadoAutocompletado> buscarEmpleados(@RequestParam(defaultValue="")String q){var filas=service.buscarEmpleados(q);return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(new ResultadoAutocompletado(filas.stream().limit(10).toList(),filas.size()>10));}
 private void menu(Authentication a,Model m){var permisos=a.getAuthorities().stream().map(x->x.getAuthority()).collect(java.util.stream.Collectors.toSet());m.addAttribute("modulos",Arrays.stream(ModuloCatalogo.values()).filter(x->x.visibleCon(permisos)).toList());m.addAttribute("moduloActual",ModuloCatalogo.EMPLEADOS);m.addAttribute("puedeAdministrar",service.permitido("EMPLEADO_ADMINISTRAR"));m.addAttribute("puedeLaboral",laboralLectura());m.addAttribute("puedeEditarLaboral",service.permitido("EMPLEADO_LABORAL_ADMINISTRAR"));m.addAttribute("puedeDocente",service.permitido("MAESTRO_ADMINISTRAR"));m.addAttribute("puedeSalarios",service.permitido("CONDICION_SALARIAL_LEER")||service.permitido("CONDICION_SALARIAL_ADMINISTRAR"));}
}
